			Search: func(c status.ComponentStatus) string { return c.Name },
		},
		{
			Title: "Target", Sizing: datatable.SizingContent, TruncateHead: true, MinWidth: 24, Flex: 2,
			Cell:   func(c status.ComponentStatus) string { return c.Target },
