			Title: "Type", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 10,
			Cell: monitorTypeCell,
			Less: func(a, b status.ComponentStatus) bool {
				return strings.ToLower(string(a.Type)) < strings.ToLower(string(b.Type))
